// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.solverimport com.roshan.persona.cognitive.model.Constraintimport com.roshan.persona.cognitive.model.ConstraintTypeimport com.roshan.persona.cognitive.model.RelaxedConstraintimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Constraint Satisfier (Module 7 v2 — Step 7.6). * * Generates solutions that satisfy ALL constraints. If no solution satisfies * all constraints, relaxes the least important one + explains why (per Q4: * ask user which to relax, or auto-relax with explanation). * * ## Algorithm * * 1. Extract constraints from the problem. * 2. Check if the proposed solution satisfies all constraints. * 3. If yes → return solution with all constraints satisfied. * 4. If no → identify which constraints are violated. * 5. Per Q4: **ask the user** which constraint to relax: *    "I can't fit everything in ₹15K. Want to increase budget or reduce days?" * 6. If user can't be asked (non-interactive) → auto-relax least important. * * ## Constraint satisfaction check * * A solution "satisfies" a constraint if: *  - BUDGET: the solution's cost ≤ the budget value. *  - TIME: the solution's time ≤ the time constraint. *  - DURATION: the solution's duration matches. *  - PREFERENCE: the solution mentions the preference keyword. *  - LOCATION: the solution mentions the location. * * For v1, satisfaction is heuristic (keyword/number matching). v2+ uses LLM. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§ProblemSolver — ConstraintSatisfier</a> */class ConstraintSatisfier(    private val dispatcher: CoroutineDispatcher,) {    /**     * Check which constraints are satisfied by [solution].     *     * @param solution the proposed solution text.     * @param constraints the constraints to check.     * @return list of satisfied constraints.     */    suspend fun checkSatisfaction(        solution: String,        constraints: List<Constraint>,    ): List<Constraint> = withContext(dispatcher) {        constraints.filter { isSatisfied(solution, it) }    }    /**     * Check which constraints are violated by [solution].     *     * @param solution the proposed solution text.     * @param constraints the constraints to check.     * @return list of violated constraints.     */    suspend fun checkViolations(        solution: String,        constraints: List<Constraint>,    ): List<Constraint> = withContext(dispatcher) {        constraints.filterNot { isSatisfied(solution, it) }    }    /**     * Determine which constraint to relax (least important = lowest type priority).     *     * Priority order (highest to lowest):     * 1. PERMISSION (can't relax — hard constraint).     * 2. BUDGET (can relax — "increase budget by ₹500").     * 3. TIME (can relax — "take a bit longer").     * 4. DURATION (can relax — "add one more day").     * 5. LOCATION (can relax — "consider nearby areas").     * 6. PREFERENCE (can relax — "compromise on comfort").     * 7. CUSTOM (depends on context).     *     * @param violated constraints that are violated.     * @return the constraint to relax, or null if none can be relaxed.     */    fun pickConstraintToRelax(violated: List<Constraint>): Constraint? {        if (violated.isEmpty()) return null        // Sort by relaxation priority (lower = more relaxable).        val sorted = violated.sortedBy { relaxationPriority(it.type) }        // PERMISSION constraints cannot be relaxed.        val relaxable = sorted.filter { it.type != ConstraintType.PERMISSION }        return relaxable.firstOrNull()    }    /**     * Build a relaxation question for the user (per Q4: ask user).     *     * @param constraint the constraint to relax.     * @return a question string, or null if the constraint can't be relaxed.     */    fun buildRelaxationQuestion(constraint: Constraint): String? {        return when (constraint.type) {            ConstraintType.BUDGET ->                "I can't fit everything within ${constraint.description.ifBlank { constraint.value }}. Want to increase the budget or reduce the scope?"            ConstraintType.TIME ->                "This needs more time than ${constraint.description.ifBlank { constraint.value }}. Is it okay to take longer?"            ConstraintType.DURATION ->                "The duration ${constraint.description.ifBlank { constraint.value }} is too tight. Want to extend it?"            ConstraintType.LOCATION ->                "I couldn't find options for ${constraint.description.ifBlank { constraint.value }}. Want to consider nearby areas?"            ConstraintType.PREFERENCE ->                "I couldn't fully meet your preference for ${constraint.description.ifBlank { constraint.value }}. Is a compromise okay?"            ConstraintType.CUSTOM ->                "I couldn't meet the constraint: ${constraint.description.ifBlank { constraint.value }}. Want to adjust it?"            ConstraintType.PERMISSION -> null  // can't relax permissions        }    }    /**     * Create a [RelaxedConstraint] with the original + relaxed value + reason.     *     * @param original the original constraint.     * @param relaxedValue the new value after relaxation.     * @param reason why it was relaxed.     */    fun createRelaxation(        original: Constraint,        relaxedValue: String,        reason: String,    ): RelaxedConstraint = RelaxedConstraint(        originalConstraint = original,        relaxedValue = relaxedValue,        reason = reason,    )    // ─── Heuristic satisfaction checks ─────────────────────────────────────    /**     * Check if [solution] satisfies [constraint].     *     * Heuristic — v1 uses keyword/number matching. v2+ uses LLM.     */    internal fun isSatisfied(solution: String, constraint: Constraint): Boolean {        val solutionLower = solution.lowercase()        val constraintValue = constraint.value.lowercase()        return when (constraint.type) {            ConstraintType.BUDGET -> {                // Extract numbers from solution + check if any ≤ budget.                val budgetAmount = constraint.value.toFloatOrNull() ?: return true  // can't parse → assume satisfied                val solutionNumbers = Regex("\\d+(?:,\\d+)*").findAll(solutionLower)                    .map { it.value.replace(",", "").toFloatOrNull() ?: 0f }                    .toList()                solutionNumbers.isEmpty() || solutionNumbers.any { it <= budgetAmount }            }            ConstraintType.TIME -> {                // v1: always satisfied (time is hard to verify heuristically).                true            }            ConstraintType.DURATION -> {                // Check if the duration value appears in the solution.                solutionLower.contains(constraintValue)            }            ConstraintType.LOCATION -> {                solutionLower.contains(constraintValue)            }            ConstraintType.PREFERENCE -> {                // For fuzzy constraints, check if the preference keyword appears.                if (constraint.isFuzzy) {                    solutionLower.contains(constraintValue) || solutionLower.contains("budget") ||                        solutionLower.contains("comfortable") || solutionLower.contains("fast")                } else {                    solutionLower.contains(constraintValue)                }            }            ConstraintType.PERMISSION -> {                // Permissions are always "satisfied" if the app has them —                // this check is handled by the executor, not the solver.                true            }            ConstraintType.CUSTOM -> {                solutionLower.contains(constraintValue)            }        }    }    /** Relaxation priority (lower = more relaxable). */    private fun relaxationPriority(type: ConstraintType): Int = when (type) {        ConstraintType.PERMISSION -> 0  // can't relax        ConstraintType.BUDGET -> 1        ConstraintType.TIME -> 2        ConstraintType.DURATION -> 3        ConstraintType.LOCATION -> 4        ConstraintType.PREFERENCE -> 5        ConstraintType.CUSTOM -> 6    }}